import { Node } from 'cc';
import { Entity } from './Entity';

export interface EntityView{
    readonly node: Node;
    bind(entity: Entity): void;
    sync(dt: number): void;
    unbind(): void;
}


export class ViewRegistry {
    private _views: Map<number, EntityView> = new Map();
    private _list: EntityView[] = [];
    private _factories: Map<string, (e: Entity) => EntityView> = new Map();
    private _layer: Node;

    constructor(layer: Node){
        this._layer = layer;
    }

    public registerFactory(e: Entity, factory: (e: Entity) => EntityView): void{
        this._factories.set(e.kind, factory);
    }

    public attach(e: Entity): EntityView | null{
        const factory = this._factories.get(e.kind);
        if(!factory){
            console.warn(`[ViewRegistry] 未注册 kind = ${e.kind} 的工厂`);
            return null;
        }

        const view = factory(e);
        view.bind(e);
        view.node.parent = this._layer;
        this._views.set(e.id, view);
        this._list.push(view);
        return view;
    }

    public detach(e: Entity): void {
        const view = this._views.get(e.id);
        if (!view) return;
        view.unbind();
        view.node.destroy();
        this._views.delete(e.id);

        const idx = this._list.indexOf(view);
        if(idx >= 0){
            this._list[idx] = this._list[this._list.length - 1];
            this._list.pop();
        }
    }

    public syncAll(dt: number): void{
        for(let i = 0; i < this._list.length; ++i){
            this._list[i].sync(dt);
        }
    }

    public clear(): void{
        for (let i = 0; i < this._list.length; i++) {
            const view = this._list[i];
            view.unbind();
            view.node.destroy();
        }
        this._views.clear();
        this._list.length = 0;
    }
}


